def compute(vars):
    total_revenue = vars["Total Revenue"]
    total_cost_of_goods_sold = vars["Total Cost of Goods Sold"]

    gross_profit = total_revenue - total_cost_of_goods_sold

    return {
        "value": gross_profit,
        "trace": {
            "Total Revenue": total_revenue,
            "Total Cost of Goods Sold": total_cost_of_goods_sold,
            "Gross Profit": gross_profit,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
